(()=>{
  const places=Array.isArray(window.TRAVEL_PLACES)?window.TRAVEL_PLACES:[];
  const tracked=places.filter(place=>place.kind!=='otel');
  let visited=[];try{const saved=JSON.parse(localStorage.getItem('asya-visited')||'[]');visited=Array.isArray(saved)?saved:[]}catch{}
  let selected='all';let filter='all';let search='';let map=null;let markerLayer=null;let markers=new Map();
  const $=selector=>document.querySelector(selector);
  const normalize=value=>String(value||'').toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const isVisited=place=>visited.includes(place.id);
  const label=place=>place.kind==='otel'?'Konaklama':place.list==='gezi'?'Gezi':'Yeme içme & alışveriş';
  const color=place=>place.kind==='otel'?'#cda46c':isVisited(place)?'#2f685e':'#a83229';
  const persist=()=>localStorage.setItem('asya-visited',JSON.stringify(visited));
  const current=()=>places.filter(place=>(selected==='all'||place.list===selected)&&(place.kind==='otel'||filter==='all'||filter==='visited'&&isVisited(place)||filter==='unvisited'&&!isVisited(place))&&(!search||normalize(place.name).includes(search)));
  function toggle(place){if(place.kind==='otel')return;visited=isVisited(place)?visited.filter(id=>id!==place.id):[...visited,place.id];persist();render()}
  function popup(place){const root=document.createElement('div');root.className='map-popup';const title=document.createElement('strong');title.textContent=place.name;const meta=document.createElement('small');meta.textContent=`${label(place)}${place.paid?' · Ücretli':''}`;root.append(title,meta);if(place.kind!=='otel'){const button=document.createElement('button');button.type='button';button.className=isVisited(place)?'visited':'';button.textContent=isVisited(place)?'✓ Gezdim':'Gezdim olarak işaretle';button.addEventListener('click',()=>toggle(place));root.append(button)}const link=document.createElement('a');link.href=`https://www.google.com/maps/dir/?api=1&destination=${place.lat},${place.lon}`;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Yol tarifi ↗';root.append(link);return root}
  function renderProgress(){const count=tracked.filter(isVisited).length;$('#map-progress').textContent=`${count} / ${tracked.length} yer gezildi`;$('#progress-fill').style.width=`${count/tracked.length*100}%`}
  function renderList(items){const root=$('#map-place-list');root.replaceChildren();$('#map-place-count').textContent=`${items.length} yer gösteriliyor`;if(!items.length){const empty=document.createElement('p');empty.className='muted-note';empty.textContent='Bu filtrede yer bulunamadı.';root.append(empty);return}for(const place of items){const row=document.createElement('div');row.className=`place-row${isVisited(place)?' visited':''}${place.kind==='otel'?' hotel':''}`;const dot=document.createElement('i');dot.className='place-dot';dot.setAttribute('aria-hidden','true');const details=document.createElement('div');const title=document.createElement('button');title.type='button';title.className='place-name';title.textContent=place.name;title.addEventListener('click',()=>{if(!map)return;map.setView([place.lat,place.lon],Math.max(map.getZoom(),14),{animate:true});markers.get(place.id)?.openPopup();$('#travel-map').scrollIntoView({behavior:'smooth',block:'center'})});const meta=document.createElement('div');meta.className='place-meta';meta.textContent=label(place);if(place.paid){const paid=document.createElement('span');paid.className='paid';paid.textContent=' · Ücretli';meta.append(paid)}details.append(title,meta);row.append(dot,details);if(place.kind!=='otel'){const button=document.createElement('button');button.type='button';button.className='visit-toggle';button.textContent=isVisited(place)?'✓ Gezdim':'Gezdim';button.setAttribute('aria-label',`${place.name}: ${isVisited(place)?'Gezilmedi olarak işaretle':'Gezdim olarak işaretle'}`);button.addEventListener('click',()=>toggle(place));row.append(button)}root.append(row)}}
  function renderMarkers(items,fit=false){if(!map)return;markerLayer.clearLayers();markers.clear();for(const place of items){const marker=L.circleMarker([place.lat,place.lon],{radius:place.kind==='otel'?9:7,color:'#fffaf0',weight:2,fillColor:color(place),fillOpacity:1}).addTo(markerLayer);marker.bindPopup(popup(place));marker.bindTooltip(place.name,{direction:'top'});markers.set(place.id,marker)}if(fit&&items.length){map.fitBounds(L.latLngBounds(items.map(place=>[place.lat,place.lon])),{padding:[24,24],maxZoom:13})}}
  function render(fit=false){const items=current();renderProgress();renderList(items);renderMarkers(items,fit)}
  function activate(){if(map){map.invalidateSize();return}if(!window.L){$('#travel-map').textContent='Harita yüklenemedi; yer listesini aşağıdan kullanabilirsin.';render();return}map=L.map('travel-map',{scrollWheelZoom:false,zoomControl:true}).setView([1.30,103.86],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>'}).addTo(map);markerLayer=L.layerGroup().addTo(map);render(true);setTimeout(()=>map.invalidateSize(),100)}
  document.querySelectorAll('[data-map-list]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.mapList;document.querySelectorAll('[data-map-list]').forEach(el=>el.classList.toggle('active',el===button));render(true)}));
  $('#place-search').addEventListener('input',event=>{search=normalize(event.target.value.trim());render(true)});
  $('#visit-filter').addEventListener('change',event=>{filter=event.target.value;render(true)});
  window.TravelMap={activate};
})();
